      "witnessCode": "import { strict as assert } from 'node:assert';\nimport { test } from 'node:test';\nimport normalizeUrl from '../index.js';\n\ntest('normalizeUrl keeps query parameters when keepQueryParameters is empty array', () => {\n  const url = 'http://example.com?a=1&b=2';\n  const options = { keepQueryParameters: [] };\n  const result = normalizeUrl(url, options);\n  // In base, query parameters should be preserved\n  assert.strictEqual(result, 'http://example.com?a=1&b=2');\n});"
